      r: 15   // 气泡半径
    }, {
      x: 30,
      y: 20,
      r: 20
    }, {
      x: 40,
      y: 10,
      r: 10
    }],
    backgroundColor: 'rgb(255, 99, 132)'
  }]
};
const config = {
  type: 'bubble', // 设置图表类型
  data: data,  // 设置数据集
  options: {
    
  },
};
const myChart = new Chart(ctx, config);

